cat << 'EOF' > calculate_fees.py
import pandas as pd
import json
import os

def get_month(day_of_year):
    # 2023 was not a leap year
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day = day_of_year
    for i, days in enumerate(days_in_months):
        if day <= days:
            return i + 1
        day -= days
    return 12

def get_volume_range(vol):
    if vol < 100000:
        return "<100k"
    elif vol < 1000000:
        return "100k-1m"
    elif vol < 5000000:
        return "1m-5m"
    else:
        return ">5m"

def get_fraud_range(ratio):
    # ratio is (fraud_vol / total_vol) * 100
    if ratio < 7.2:
        return "<7.2%"
    elif ratio < 7.7:
        return "7.2%-7.7%"
    elif ratio < 8.3:
        return "7.7%-8.3%"
    else:
        return ">8.3%"

def get_capture_delay_range(cd):
    if cd in ["immediate", "manual"]:
        return cd
    try:
        val = int(cd)
        if val < 3:
            return "<3"
        elif 3 <= val <= 5:
            return "3-5"
        else:
            return ">5"
    except:
        return cd

# Load merchant data
with open('/data/merchant_data.json', 'r') as f:
    merchants = json.load(f)

target_merchant = "Belles_cookbook_store"
merchant_info = next(m for m in merchants if m['merchant'] == target_merchant)
m_mcc = merchant_info['merchant_category_code']
m_account_type = merchant_info['account_type']
m_capture_delay = get_capture_delay_range(merchant_info['capture_delay'])

# Load fees
with open('/data/fees.json', 'r') as f:
    fees = json.load(f)

# Load payments
df = pd.read_csv('/data/payments.csv')
df_2023 = df[(df['merchant'] == target_merchant) & (df['year'] == 2023)].copy()

# Add month
df_2023['month'] = df_2023['day_of_year'].apply(get_month)

# Calculate monthly metrics
monthly_metrics = {}
for month in range(1, 13):
    m_df = df_2023[df_2023['month'] == month]
    total_vol = m_df['eur_amount'].sum()
    fraud_vol = m_df[m_df['has_fraudulent_dispute'] == True]['eur_amount'].sum()
    fraud_ratio = (fraud_vol / total_vol * 100) if total_vol > 0 else 0
    monthly_metrics[month] = {
        'volume_range': get_volume_range(total_vol),
        'fraud_range': get_fraud_range(fraud_ratio)
    }

total_fees = 0

for _, row in df_2023.iterrows():
    month = row['month']
    m_vol_range = monthly_metrics[month]['volume_range']
    m_fraud_range = monthly_metrics[month]['fraud_range']

    is_intra = row['issuing_country'] == row['acquirer_country']

    tx_fees = 0
    for rule in fees:
        # Match card_scheme
        if rule['card_scheme'] is not None and rule['card_scheme'] != row['card_scheme']:
            continue

        # Match account_type (list)
        if rule['account_type'] and m_account_type not in rule['account_type']:
            continue

        # Match capture_delay
        if rule['capture_delay'] is not None and rule['capture_delay'] != m_capture_delay:
            continue

        # Match monthly_fraud_level
        if rule['monthly_fraud_level'] is not None and rule['monthly_fraud_level'] != m_fraud_range:
            continue

        # Match monthly_volume
        if rule['monthly_volume'] is not None and rule['monthly_volume'] != m_vol_range:
            continue

        # Match merchant_category_code (list)
        if rule['merchant_category_code'] and m_mcc not in rule['merchant_category_code']:
            continue

        # Match is_credit
        if rule['is_credit'] is not None and rule['is_credit'] != row['is_credit']:
            continue

        # Match aci (list)
        if rule['aci'] and row['aci'] not in rule['aci']:
            continue

        # Match intracountry
        if rule['intracountry'] is not None:
            rule_intra = bool(rule['intracountry'])
            if rule_intra != is_intra:
                continue

        # All matched
        tx_fees += rule['fixed_amount'] + (rule['rate'] * row['eur_amount'] / 10000)

    total_fees += tx_fees

print(f"{total_fees:.4f}")
EOF
